<div class="ef-page"><div class="ef-shell"><a class="ef-back" href="<?= site_url('sd-login') ?>" aria-label="Back to login"><svg viewBox="0 0 24 24" fill="none"><path d="M19 12H5" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="m12 19-7-7 7-7" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></a><div class="ef-brand"><img src="https://efactor.tech/assets/images/efactor-logo_light.png" data-logo-light="https://efactor.tech/assets/images/efactor-logo.png" data-logo-dark="https://efactor.tech/assets/images/efactor-logo_light.png" alt="Efactor"></div><div class="ef-scroll"><main class="ef-card" aria-labelledby="forgotTitle"><div class="ef-heading-wrap"><h1 class="ef-title" id="forgotTitle">Reset Password</h1><p class="ef-subtitle">Enter your mobile number and OTP to set a new password.</p></div><?php if ($success): ?><div class="ef-alert"><?= esc($success) ?></div><?php endif; ?><form action="<?= site_url('sd-forgot-password') ?>" method="post" novalidate><?= csrf_field() ?><div class="ef-field"><div class="ef-input"><svg class="ef-icon" viewBox="0 0 24 24" fill="none"><rect width="14" height="20" x="5" y="2" rx="2" stroke="currentColor" stroke-width="1.8"/><path d="M12 18h.01" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg><input class="ef-control" id="reset_phone" name="phone" type="tel" inputmode="numeric" maxlength="10" placeholder="Enter phone number" required></div><button class="ef-send-otp" type="button" id="resetSendOtpButton">Send OTP</button><div class="ef-error"><?= ($validation ? $validation->getError('phone') : '') ?></div></div><div class="ef-otp" id="resetOtpSection"><div class="ef-otp-boxes"><input class="ef-otp-box" maxlength="1" inputmode="numeric" aria-label="OTP digit 1"><input class="ef-otp-box" maxlength="1" inputmode="numeric" aria-label="OTP digit 2"><input class="ef-otp-box" maxlength="1" inputmode="numeric" aria-label="OTP digit 3"><input class="ef-otp-box" maxlength="1" inputmode="numeric" aria-label="OTP digit 4"><input class="ef-otp-box" maxlength="1" inputmode="numeric" aria-label="OTP digit 5"><input class="ef-otp-box" maxlength="1" inputmode="numeric" aria-label="OTP digit 6"></div><button class="ef-send-otp" type="button" id="resetResendOtpButton">Resend OTP</button><input type="hidden" name="otp" id="reset_otp"><div class="ef-error"><?= ($validation ? $validation->getError('otp') : '') ?></div></div><div class="ef-password-block" id="resetPasswordBlock"><div class="ef-field"><div class="ef-input"><svg class="ef-icon" viewBox="0 0 24 24" fill="none"><rect width="18" height="11" x="3" y="11" rx="2" stroke="currentColor" stroke-width="1.8"/><path d="M7 11V7a5 5 0 0 1 10 0v4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg><input class="ef-control" id="reset_password" name="password" type="password" maxlength="72" placeholder="New password" required><button class="ef-toggle" type="button" data-password-toggle="reset_password" aria-label="Show password"><svg viewBox="0 0 24 24" fill="none"><path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0" stroke="currentColor" stroke-width="1.8"/><circle cx="12" cy="12" r="3" stroke="currentColor" stroke-width="1.8"/></svg></button></div><div class="ef-error"><?= ($validation ? $validation->getError('password') : '') ?></div></div><div class="ef-field"><div class="ef-input"><svg class="ef-icon" viewBox="0 0 24 24" fill="none"><path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z" stroke="currentColor" stroke-width="1.8"/><path d="m9 12 2 2 4-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><input class="ef-control" id="reset_confirm_password" name="confirm_password" type="password" maxlength="72" placeholder="Confirm password" required><button class="ef-toggle" type="button" data-password-toggle="reset_confirm_password" aria-label="Show confirm password"><svg viewBox="0 0 24 24" fill="none"><path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0" stroke="currentColor" stroke-width="1.8"/><circle cx="12" cy="12" r="3" stroke="currentColor" stroke-width="1.8"/></svg></button></div><div class="ef-error"><?= ($validation ? $validation->getError('confirm_password') : '') ?></div></div></div><button class="ef-submit" type="submit">Reset password</button></form></main><footer class="ef-footer">Remembered it? <a class="ef-link" href="<?= site_url('sd-login') ?>">Sign in</a></footer></div></div></div><script>document.addEventListener('DOMContentLoaded',function(){var boxes=[].slice.call(document.querySelectorAll('.ef-otp-box'));var hidden=document.getElementById('reset_otp');var phone=document.getElementById('reset_phone'),send=document.getElementById('resetSendOtpButton'),resend=document.getElementById('resetResendOtpButton'),section=document.getElementById('resetOtpSection'),passwords=document.getElementById('resetPasswordBlock');function sync(){if(hidden)hidden.value=boxes.map(function(b){return b.value}).join('')}function digits(){return phone?phone.value.replace(/\D/g,'').slice(0,10):''}function showOtp(){if(section)section.classList.add('is-visible');if(passwords)passwords.classList.add('is-visible');if(send)send.style.display='none'}function requestOtp(){if(digits().length!==10){phone&&phone.focus();return}if(phone)phone.value=digits();showOtp();var cfg=window.SD_AUTH||{},body=new URLSearchParams();body.append('phone',digits());if(cfg.csrfName&&cfg.csrfHash)body.append(cfg.csrfName,cfg.csrfHash);if(cfg.otpUrl)fetch(cfg.otpUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body:body.toString()}).then(function(r){return r.json()}).then(function(data){if(data&&data.csrfHash){cfg.csrfHash=data.csrfHash;window.SD_AUTH=cfg}}).catch(function(){});if(boxes[0])boxes[0].focus()}if(phone)phone.addEventListener('input',function(){phone.value=digits()});if(send)send.addEventListener('click',requestOtp);if(resend)resend.addEventListener('click',requestOtp);boxes.forEach(function(box,i){box.addEventListener('input',function(){box.value=box.value.replace(/\D/g,'').slice(0,1);sync();if(box.value&&boxes[i+1])boxes[i+1].focus()});box.addEventListener('keydown',function(e){if(e.key==='Backspace'&&!box.value&&boxes[i-1])boxes[i-1].focus()})});document.querySelectorAll('[data-password-toggle]').forEach(function(button){button.addEventListener('click',function(){var input=document.getElementById(button.dataset.passwordToggle);if(!input)return;input.type=input.type==='password'?'text':'password'})})});</script>
